if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_kind() {
    procs --list | gawk 'NR > 1 {
        line = $0
        sub(/^[[:space:]]+/, "", line)
        idx = index(line, ":")
        if (idx == 0) {
            next
        }
        kind = substr(line, 1, idx - 1)
        sub(/[[:space:]]+$/, "", kind)
        desc = substr(line, idx + 1)
        sub(/^[[:space:]]+/, "", desc)
        if (kind != "") {
            print kind "\t" desc
        }
    }'
}
